"""Unit 7: Tagalog Basic Course, Semester I, Unit 2, Chapter 2, Lesson 2: Personal Identification (Nationality and Religion).
Original lessons; the scope follows the DLIFLC Tagalog Basic Course (Teacher Edition, December 2020).
Audio, pictures, partner and group work are left out; the book's answer keys are used where it prints them,
and the English notes are mine."""
from dsl_tl import *


def dd(xs, ans, n=3, extra=()):
    out = []
    for x in list(xs) + list(extra):
        if x != ans and x not in out:
            out.append(x)
    return out[:n]


# ------------------------------------------------------------------ 1 nationalities
_NATG = [("Aleman", "German", "Aleman siya."), ("Amerikano", "American", "Amerikano tayo."), ("Arabe", "Arab", "Arabe ang mga estudyante."), ("Australyano", "Australian", "Australyano si Richard."), ("Biyetnamis", "Vietnamese", "Biyetnamis ako."), ("Briton", "British", "Briton ang guro ko."), ("Espanyol", "Spaniard, Spanish", "Espanyol ang guro namin."), ("Griyego", "Greek", "Griyego ang tatay niya."), ("Hapon", "Japanese", "Hapon ang nanay nila."), ("Indones", "Indonesian", "Indones ang guro natin."), ("Ingles", "English", "Ingles ang bayaw ni Gabby."), ("Intsik", "Chinese", "Intsik ang manugang ni Cresencio."), ("Italyano", "Italian", "Italyano ang estudyante niya."), ("Pilipino", "Filipino", "Ikaw ay Pilipino."), ("Portuges", "Portuguese", "Portuges ka."), ("Pranses", "French", "Pranses kami.")]
_NATQ = [("Ano ang nasyonalidad nina Julianne at Gracia?", "What is the nationality of Julianne and Gracia?"), ("Pilipino ang nasyonalidad nina Julianne at Gracia.", "The nationality of Julianne and Gracia is Filipino."), ("Pilipino sina Julianne at Gracia.", "Julianne and Gracia are Filipinos."), ("Pilipino sila.", "They are Filipinos."), ("Sila ay Pilipino.", "They are Filipinos.")]
