        + tr_q(_NATQ) + tr_q(_CONTR) + rev_q(_CONTR[:4])
        + [M(f"What does {s} mean?", e, dd([x for _, x, _ in _NATG], e, 3), f"{s}") for _, e, s in _NATG[:0]]
        + [M("What does naman show in Pilipino si Julianne, Aleman naman si Gracia?", "Contrast between two persons", ["A question", "Plurality", "Past time"], "naman = while, on the other hand."), M("What does nasyonalidad mean?", "nationality", ["religion", "family", "classroom"], "nasyonalidad."), M("What does Ano ang nasyonalidad ni Maria? ask?", "What is Maria’s nationality?", ["What is Maria’s religion?", "How old is Maria?", "Who is Maria?"], "nasyonalidad = nationality."), M("Which words are Tagalog for “Japanese” and “Chinese”?", "Hapon and Intsik", ["Aleman and Briton", "Griyego and Italyano", "Pranses and Portuges"], "Hapon, Intsik."), M("Which words mean “Greek” and “Italian”?", "Griyego and Italyano", ["Hapon and Intsik", "Briton and Ingles", "Arabe and Indones"], "Griyego, Italyano."), M("Which Tagalog word is “French”?", "Pranses", ["Portuges", "Espanyol", "Aleman"], "Pranses."), M("Which Tagalog word is “Portuguese”?", "Portuges", ["Pranses", "Espanyol", "Italyano"], "Portuges."), M("Which two words mean “English” and “British”?", "Ingles and Briton", ["Pranses and Briton", "Aleman and Ingles", "Hapon and Briton"], "Ingles, Briton.")]
