# ------------------------------------------------------------------ 3 Set II possessive markers and ano
_PC = [("Matangkad ang kuya ni Jobert.", "Jobert’s oldest brother is tall."), ("Maganda ang ate ni Lulu.", "Lulu’s oldest sister is beautiful."), ("Mabait ang nanay nina Bambam at Noynoy.", "Bambam and Noynoy’s mother is nice."), ("Matalino ang tito nina Jingjing at Bobot.", "Jingjing and Bobot’s uncle is intelligent."), ("Maliit ang silid-aralan ng sundalo.", "The soldier’s classroom is small."), ("Malinis ang kuwarto ng sundalo.", "The soldier’s room is clean."), ("Malaki ang bahay ng mga titser.", "The teachers’ house is big."), ("Masikip ang opisina ng mga titser.", "The teachers’ office is cramped.")]
_SM2 = [("ni", "a person’s name"), ("nina", "names of two or more persons"), ("ng", "singular common nouns"), ("ng mga", "plural common nouns")]
_ANOQ = [("Ano ang relihiyon ni Nicolas?", "What is Nicolas’ religion?"), ("Ano ang nasyonalidad nina Julianne at Gracia?", "What is Julianne and Gracia’s nationality?")]
_ANOS = [("Ano ang + noun + ni + name of a person", "Ano ang relihiyon ni Nicolas?"), ("Ano ang + noun + nina + names of at least two persons", "Ano ang nasyonalidad nina Julianne at Gracia?"), ("Ano ang + noun + ng + singular common noun", "Ano ang kulay ng papel?"), ("Ano ang + noun + ng mga + plural common noun", "Ano ang relihiyon ng mga guro?")]
_VC = [("matangkad", "tall"), ("maganda", "beautiful"), ("mabait", "nice, good, kind"), ("matalino", "intelligent, smart"), ("maliit", "small"), ("malinis", "clean"), ("malaki", "big"), ("masikip", "tight, narrow, cramped"), ("silid-aralan", "classroom"), ("kuwarto", "room"), ("bahay", "house"), ("opisina", "office"), ("titser", "teacher")]
L3 = lesson(
    "C2 L2 · Set II possessive markers: ni, nina, ng, ng mga",
    "ang kuya ni Jobert · ang nanay nina Bambam at Noynoy · ang bahay ng mga titser · Ano ang …?",
    requires=[],
    cards=[
        card("Passage C: sentences with ni, nina, ng and ng mga", "The predicates of these sentences are nouns, pronouns or adjectives; such sentences are called equational sentences. In English the predicate and the subject are joined by the linking verb “to be”, but Tagalog has no “to be” linking verb. Matangkad, maganda, mabait, matalino, maliit, malinis, malaki and masikip are ma adjectives.", examples=passage(_PC), tables=[ttable(_VC)]),
        card("The Set II possessive markers", "Like the Set II pronouns, the Set II markers come before the noun they modify. They translate as “of” or “’s” (and sometimes “s’”). They also mark the noun that does the action in some sentences where the focus is on the object, which you will see with the verbs.", tables=[table(["Set II marker", "Use with"], [list(r) for r in _SM2], say=[0])]),
        card("Translations of the book’s sentences", "Each sentence can be translated in two ways: Jobert’s oldest brother is tall, or The oldest brother of Jobert is tall.", examples=passage(_PC)),
        card("The interrogative ano", "Ano means “what”. It usually refers to things, but it is also used with people when the expected answers are professions (rank, title), gender, status (marital, immigration, social), religion or nationality.", examples=passage(_ANOQ), tables=[table(["Structure", "Example"], [list(r) for r in _ANOS], say=[1])]),
        card("Matching: the book’s checks", "The adjectives describing the persons and things in the comprehension check (a): kuya, tall; ate, beautiful; nanay, nice; tito, intelligent; classroom, small; room, clean; house, big; office, tight."),
        card("Activities left out", "Making three simple sentences of your own from the structure Adjective + noun + Set II marker + noun."),
    ],
    exercises=uniq(
        tr_q(_PC) + rev_q(_PC[:6]) + tr_q(_ANOQ) + tr_q(_VC) + rev_q(_VC[:10])
        + [M(f"Which marker goes with {u}?", m, [x for x, _ in _SM2 if x != m], f"{m} goes with {u}.") for m, u in _SM2]
        + [M("What do the Set II markers translate to in English?", "of or ’s", ["the", "is", "and"], "of, ’s."), M("Where do the Set II markers appear?", "Before the noun they modify", ["After the noun", "At the end of the sentence", "Before the verb"], "They precede the noun."), M("Is there a “to be” linking verb in Tagalog equational sentences?", "No", ["Yes, ay is always required", "Yes, si", "Only in questions"], "There is no “to be” verb."), M("Which questions can ano ask about people?", "Profession, gender, status, religion, nationality", ["Only names", "Only age", "Only places"], "Ano also covers these."), M("Which sentence means “The soldier’s room is clean”?", "Malinis ang kuwarto ng sundalo.", ["Malinis ang kuwarto ni sundalo.", "Malinis ang kuwarto nina sundalo.", "Malinis ang kuwarto ng mga sundalo."], "ng + singular common noun."), M("Which sentence means “The teachers’ house is big”?", "Malaki ang bahay ng mga titser.", ["Malaki ang bahay ng titser.", "Malaki ang bahay ni titser.", "Malaki ang bahay nina titser."], "ng mga + plural."), M("Which is a ma adjective?", "mabait", ["bahay", "opisina", "titser"], "ma + bait."), M("What is the root of matalino?", "talino", ["ma", "alino", "tali"], "ma + talino."), M("What is the root of maliit?", "liit", ["ma", "alit", "liita"], "ma + liit."), M("What is the root of malaki?", "laki", ["ma", "alak", "lak"], "ma + laki.")]
        + [F("Matangkad ang kuya ___ Jobert.", "ni", ["nina", "ng"], "ni + one name."), F("Mabait ang nanay ___ Bambam at Noynoy.", "nina", ["ni", "ng mga"], "nina + two names."), F("Maliit ang silid-aralan ___ sundalo.", "ng", ["ni", "nina"], "ng + common noun."), F("Malaki ang bahay ng ___ titser.", "mga", ["ni", "sina"], "ng mga titser."), F("Ano ang relihiyon ___ Nicolas?", "ni", ["nina", "ng"], "ni Nicolas."), F("___ ang kuwarto ng sundalo. (clean)", "Malinis", ["Maliit", "Masikip"], "Malinis ang kuwarto ng sundalo.")]
    ),
)

